// A generic, type-safe array chunker
class Chunker<T> {
    co(chunkCount, items);
    pri v chunkCount : int;
    pri v items : [T, *];

    fn chunks() : [[T, *], *] {
        v chunks : [[T, *], *];
        v temp : [T, self.chunkCount];
        for i : self.items.len {
            if temp.len == self.chunkCount {
                chunks.push(temp);
                temp.clean();
            } else {
                temp.push(this.items[i]!);
            }
        }
        ret chunks;
    }
}

